<?php namespace App\Http\Controllers\Api\V1;
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use App\Models\{Student,Teacher,SchoolClass,Subject,Period,Timetable,Homework,Notice,HomeworkSubmission,ParentModel};
class CrudController extends Controller {
 protected array $map=['classes'=>SchoolClass::class,'subjects'=>Subject::class,'periods'=>Period::class,'timetables'=>Timetable::class,'homework'=>Homework::class,'notices'=>Notice::class];
 public function index(Request $r){$m=$this->map[$r->route('resource')]??null; if(!$m)return $this->fail('Invalid resource',404); $q=$m::query()->where('school_id',$r->user()->school_id); if($r->search)$q->where('name','ilike','%'.$r->search.'%'); return $this->ok($q->paginate(min((int)$r->per_page?:20,100)));}
 public function store(Request $r){$resource=$r->route('resource'); $m=$this->map[$resource]??null; if(!$m)return $this->fail('Invalid resource',404); $this->authorizeRole($r,['super_admin','admin','teacher']); $data=$r->all(); $data['school_id']=$r->user()->school_id; return $this->ok($m::create($data),'Created',201);}
 public function update(Request $r,$id){$m=$this->map[$r->route('resource')]??null;if(!$m)return $this->fail('Invalid resource',404);$x=$m::where('school_id',$r->user()->school_id)->findOrFail($id);$x->update($r->all());return $this->ok($x,'Updated');}
 public function destroy(Request $r,$id){$m=$this->map[$r->route('resource')]??null;if(!$m)return $this->fail('Invalid resource',404);$this->authorizeRole($r,['super_admin','admin']);$m::where('school_id',$r->user()->school_id)->findOrFail($id)->delete();return $this->ok(null,'Deleted');}
 public function students(Request $r){$q=Student::with('parent')->where('school_id',$r->user()->school_id);if($r->search)$q->where(fn($x)=>$x->where('name','ilike','%'.$r->search.'%')->orWhere('admission_no','ilike','%'.$r->search.'%'));foreach(['class_id','section_id','status'] as $f)if($r->$f!==null)$q->where($f,$r->$f);return $this->ok($q->paginate(min((int)$r->per_page?:20,100)));}
 public function createStudent(Request $r){$this->authorizeRole($r,['super_admin','admin']);$d=$r->validate(['name'=>'required|string','admission_no'=>'required|string','roll_no'=>'nullable|string','class_id'=>'nullable|integer','section_id'=>'nullable|integer','parent_id'=>'nullable|integer','status'=>'nullable|string']);$d['school_id']=$r->user()->school_id;return $this->ok(Student::create($d),'Student created',201);}
 public function updateStudent(Request $r,$id){$this->authorizeRole($r,['super_admin','admin']);$s=Student::where('school_id',$r->user()->school_id)->findOrFail($id);$s->update($r->all());return $this->ok($s,'Student updated');}
 public function deleteStudent(Request $r,$id){$this->authorizeRole($r,['super_admin','admin']);Student::where('school_id',$r->user()->school_id)->findOrFail($id)->delete();return $this->ok(null,'Student deleted');}
 public function teachers(Request $r){return $this->ok(Teacher::with(['user','subjects','classes'])->where('school_id',$r->user()->school_id)->paginate(20));}
 public function createTeacher(Request $r){$this->authorizeRole($r,['super_admin','admin']);$d=$r->validate(['name'=>'required|string','email'=>'required|email','phone'=>'nullable|string','joining_date'=>'nullable|date']);$d['school_id']=$r->user()->school_id;return $this->ok(Teacher::create($d),'Teacher created',201);}
 public function assignClasses(Request $r,$id){$this->authorizeRole($r,['super_admin','admin']);$t=Teacher::where('school_id',$r->user()->school_id)->findOrFail($id);$t->classes()->sync($r->validate(['class_ids'=>'required|array','class_ids.*'=>'integer'])['class_ids']);return $this->ok($t->load('classes'),'Classes assigned');}
 public function importStudents(Request $r){$this->authorizeRole($r,['super_admin','admin']);return $this->csv($r,Student::class,'students');} public function importTeachers(Request $r){$this->authorizeRole($r,['super_admin','admin']);return $this->csv($r,Teacher::class,'teachers');}
 protected function csv($r,$model,$type){$r->validate(['file'=>'required|file|mimes:csv,txt|max:5120']);$h=fopen($r->file('file')->getRealPath(),'r');$head=fgetcsv($h);$ok=0;$bad=[];$row=1;while(($v=fgetcsv($h))!==false){$row++;$d=array_combine($head,$v);try{$d['school_id']=$r->user()->school_id;$model::create($d);$ok++;}catch(\Throwable $e){$bad[]=['row'=>$row,'error'=>$e->getMessage()];}}return $this->ok(['imported'=>$ok,'failed'=>$bad],'CSV processed');}
 public function studentQr(Request $r,$id){$s=Student::where('school_id',$r->user()->school_id)->findOrFail($id);return $this->ok(['student_id'=>$s->id,'admission_no'=>$s->admission_no,'name'=>$s->name,'qr_payload'=>base64_encode(json_encode(['student_id'=>$s->id,'admission_no'=>$s->admission_no]))]);}
 public function submissions(Request $r){return $this->ok(HomeworkSubmission::where('school_id',$r->user()->school_id)->paginate(20));}
}
